    let size = textureDimensions(sourceTexture);

    if (id.x >= size.x || id.y >= size.y) {
        return;
    }

    let coordinate = vec2<i32>(i32(id.x), i32(id.y));
    // Row zero is the field ceiling, so the world y of a row counts down from the field height.
